run:
(root) => {
    const cv = root.querySelector('.cv');
    const ctx = cv.getContext('2d');
    let w = 0;
    let h = 0;
    let dpr = 1;
    const ps = [];
    const fit = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = root.clientWidth;
      h = root.clientHeight;
      cv.width = Math.round(w * dpr);
      cv.height = Math.round(h * dpr);
    };
    fit();
    for (let i = 0; i < 70; i++) {
      const z = Math.random();
      ps.push({ x: Math.random(), y: Math.random(), z, ph: Math.random() * 6.28 });
    }
    let last = 0;
    let t = 0;
    const loop = (now) => {
      if (!root.isConnected) return;
      requestAnimationFrame(loop);
      const dt = now - last;
      last = now;
      if (root.dataset.paused || dt > 200) return;
      if (root.clientWidth !== w || root.clientHeight !== h) fit();
      t += dt / 1000;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      for (const p of ps) {
        p.y -= (dt / 1000) * (0.02 + p.z * 0.09);
        if (p.y < -0.05) {
          p.y = 1.05;
          p.x = Math.random();
        }
        const x = (p.x + Math.sin(t * 0.5 + p.ph) * 0.012 * (0.4 + p.z)) * w;
        const y = p.y * h;
        const r = 0.9 + p.z * 2.6;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, 6.2832);
        ctx.fillStyle = 'rgba(255,68,51,' + (0.14 + p.z * 0.5).toFixed(2) + ')';
        ctx.fill();
      }
    };
    requestAnimationFrame(loop);
  }

